class Solution {
public:
    vector<int> sameEndSubstringCount(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<vector<int>> pref(n + 1, vector<int>(26, 0));
        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 26; c++) pref[i + 1][c] = pref[i][c];
            pref[i + 1][s[i] - 'a']++;
        }
        vector<int> ans;
        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            int total = 0;
            for (int c = 0; c < 26; c++) {
                int k = pref[r + 1][c] - pref[l][c];
                total += k * (k + 1) / 2;
            }
            ans.push_back(total);
        }
        return ans;
    }
};

class Solution {
    public int[] sameEndSubstringCount(String s, int[][] queries) {
        int n = s.length();
        int[][] pref = new int[n + 1][26];
        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 26; c++) pref[i + 1][c] = pref[i][c];
            pref[i + 1][s.charAt(i) - 'a']++;
        }
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            int total = 0;
            for (int c = 0; c < 26; c++) {
                int k = pref[r + 1][c] - pref[l][c];
                total += k * (k + 1) / 2;
            }
            ans[qi] = total;
        }
        return ans;
    }
}

/**
 * @param {string} s
