var sameEndSubstringCount = function(s, queries) {
    const n = s.length;
    const pref = Array.from({ length: n + 1 }, () => new Int32Array(26));
    for (let i = 0; i < n; i++) {
        for (let c = 0; c < 26; c++) pref[i + 1][c] = pref[i][c];
        pref[i + 1][s.charCodeAt(i) - 97]++;
    }
    const ans = new Int32Array(queries.length);
    for (let qi = 0; qi < queries.length; qi++) {
        const [l, r] = queries[qi];
        let total = 0;
        for (let c = 0; c < 26; c++) {
            const k = pref[r + 1][c] - pref[l][c];
            total += (k * (k + 1)) >> 1;
        }
        ans[qi] = total;
    }
    return Array.from(ans);
};
